def entry_message(t):
    return ("EDUCATION PURPOSE ONLY\n" f"Strategy B PAPER ENTRY | ID {t['trade_id']}\n" f"{t['symbol']} {t['side']} | signal {t['signal_time']} IST | entry {t['entry_time']} IST @ {t['entry']:.2f}\n" f"SL {t['sl']:.2f} | TP {t['target']:.2f} | qty {t['quantity']} | notional ₹{t['notional']:.2f}\n" f"NIFTY trend {t.get('nifty_trend','UNVERIFIED')} | POC {t.get('poc_status','UNVERIFIED')}\n" f"Sweep {t.get('sweep','UNVERIFIED')} | Displacement {t.get('displacement','UNVERIFIED')} | MSS {t.get('mss','UNVERIFIED')} | FVG/OB {t.get('zone','UNVERIFIED')} | Retest {t.get('retest','UNVERIFIED')}\nPaper simulation only; no broker order sent.")
def close_message(t,s):
    return (f"Strategy B PAPER CLOSE | ID {t['trade_id']}\n{t['symbol']} {t['side']} | {t['result']} | exit {t['exit']:.2f} at {t['exit_time']} IST | reason {t['exit_reason']}\n" f"Gross P&L ₹{t['gross_pnl']:.2f} | closed {s['trades']} | win rate {s['win_rate']:.2f}% | gross profit ₹{s['gross_profit']:.2f} | gross loss ₹{s['gross_loss']:.2f} | PF {s['profit_factor']:.3f} | cumulative ₹{s['gross_pnl']:.2f}")
